/**
 * The one way health reads `index.db`: read-only, refusing a damaged file, closed after the read. A read that fails
 * while a first build holds the rebuild lock reports `building` (the partial index is expected), not an error.
 */
import { toErrorMessage } from "../../core/common.js";
import { getDbPath } from "../../core/paths.js";
import { heldRebuildLock } from "../../indexer/index-rebuild-lock.js";
import { closeDatabase, indexDbIsDamaged, openReadonlyExistingDatabase, } from "../../storage/repositories/index-connection.js";
export function readHealthIndex(read) {
    try {
        if (indexDbIsDamaged())
            throw new Error("index.db is damaged");
        const db = openReadonlyExistingDatabase(getDbPath());
        if (!db)
            return { noIndex: true };
        try {
            return { value: read(db) };
        }
        finally {
            closeDatabase(db);
        }
    }
    catch (error) {
        if (heldRebuildLock())
            return { building: true };
        return { error: toErrorMessage(error) };
    }
}
